                const state = (poleCount === 4) ? sxTetradState : (poleCount === 5) ? sxPentadState : (poleCount === 6) ? sxHexadState : (poleCount === 7) ? sxHeptadState : sxOctadState;
                const mode = state.mode || "advocacy";
